                ~zone3Notes.do { |arr| if(arr.notNil) { arr.do(_.set(\gate, 0)) } };
                ~zone2Notes = Array.newClear(128);
                ~zone3Notes = Array.newClear(128);
            });

        ~mainWin.front;

        // Polling loop
        Routine({
            while { ~mainWin.notNil and: { ~mainWin.isClosed.not } } {
